const setListingStockAndStatus = `-- name: SetListingStockAndStatus :one
UPDATE listings SET stock = $1, status = $2, updated_at = now()
WHERE id = $3
RETURNING id, seller_id, product_id, variety, description, price_som, unit, min_order, stock, trade_type, region_id, market_id, status, review_note, valid_until, views, created_at, updated_at, review_reason, price_min, price_max, pricing_mode, pricing_goal, manual_price_at
`

type SetListingStockAndStatusParams struct {
	Stock  pgtype.Numeric `json:"stock"`
	Status string         `json:"status"`
	ID     int64          `json:"id"`
}

func (q *Queries) SetListingStockAndStatus(ctx context.Context, arg SetListingStockAndStatusParams) (Listing, error) {
	row := q.db.QueryRow(ctx, setListingStockAndStatus, arg.Stock, arg.Status, arg.ID)
	var i Listing
	err := row.Scan(
		&i.ID,
		&i.SellerID,
		&i.ProductID,
		&i.Variety,
		&i.Description,
		&i.PriceSom,
		&i.Unit,
		&i.MinOrder,
		&i.Stock,
		&i.TradeType,
		&i.RegionID,
		&i.MarketID,
		&i.Status,
		&i.ReviewNote,
		&i.ValidUntil,
		&i.Views,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ReviewReason,
		&i.PriceMin,
		&i.PriceMax,
		&i.PricingMode,
		&i.PricingGoal,
		&i.ManualPriceAt,
	)
	return i, err
}

const todaysContactsBySeller = `-- name: TodaysContactsBySeller :many
SELECT l.seller_id, u.telegram_id, l.id AS listing_id, p.name AS product_name, l.variety, count(*)::int AS contacts
FROM listing_events e
JOIN listings l ON l.id = e.listing_id
JOIN products p ON p.id = l.product_id
JOIN users u ON u.id = l.seller_id
WHERE e.kind = 'contact' AND e.day = (now() AT TIME ZONE 'Asia/Tashkent')::date AND u.bot_enabled
GROUP BY l.seller_id, u.telegram_id, l.id, p.name, l.variety
ORDER BY l.seller_id, contacts DESC, l.id
`

type TodaysContactsBySellerRow struct {
	SellerID    uuid.UUID `json:"seller_id"`
	TelegramID  int64     `json:"telegram_id"`
	ListingID   int64     `json:"listing_id"`
	ProductName string    `json:"product_name"`
	Variety     string    `json:"variety"`
	Contacts    int32     `json:"contacts"`
}

// Today's contact reveals per listing for the sellers' evening question.
func (q *Queries) TodaysContactsBySeller(ctx context.Context) ([]TodaysContactsBySellerRow, error) {
	rows, err := q.db.Query(ctx, todaysContactsBySeller)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TodaysContactsBySellerRow{}
	for rows.Next() {
		var i TodaysContactsBySellerRow
		if err := rows.Scan(
			&i.SellerID,
			&i.TelegramID,
			&i.ListingID,
			&i.ProductName,
			&i.Variety,
			&i.Contacts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
